RX = [
 ("^\\(about (\\d+) minutes?\\)$", "function(m,n){return '(takribani dakika '+n+')'}"),
 ("^(\\d+) saved responses?$", "function(m,n){return 'majibu '+n+' yaliyohifadhiwa'}"),
 ("^(\\d+) separate narrative records?$", "function(m,n){return 'rekodi '+n+' tofauti za maelezo'}"),
 ("^(\\d+) last month$", "function(m,n){return n+' mwezi uliopita'}"),
 ("^Check-ins this month, from (\\d+) students$", "function(m,n){return 'Tathmini mwezi huu, kutoka kwa wanafunzi '+n}"),
 ("^([\\u25b2\\u25bc]) ([\\d.]+) (points|h) (better|worse)$", "function(m,a,n,u,w){return a+' '+(u==='h'?'saa ':'pointi ')+n+(w==='better'?' bora zaidi':' mbaya zaidi')}"),
 ("^(\\w+) \\(to (\\d+)th\\)$", "function(m,mo,d){return (SW_DICT[mo]||mo)+' (hadi tarehe '+d+')'}"),
 ("^Signed in as Nurse counsellor \\(demo\\) \\u00b7 (\\d+) open \\u00b7$", "function(m,n){return 'Umeingia kama muuguzi mshauri (majaribio) \\u00b7 wazi '+n+' \\u00b7'}"),
 ("^Received (\\S+ \\w+) ago \\u00b7 (.*)$", "function(m,t,r){return 'Imepokelewa '+t.replace('d','siku').replace('h','saa').replace('min','dak')+' zilizopita \\u00b7 '+r.replace('overdue','imechelewa').replace(/in /,'baada ya ')}"),
 ("^(Call-back|Question|Welfare) \\u00b7 (.+)$", "function(m,a,b){return (SW_DICT[a]||a)+' \\u00b7 '+(SW_DICT[b]||b)}"),
 ("^overdue (.+)$", "function(m,t){return 'imechelewa '+t}"),
 ("^in (\\d+[dh] .+)$", "function(m,t){return 'baada ya '+t}"),
 ("^usage count: (.+)$", "function(m,t){return 'hesabu ya matumizi: '+t}"),
 ("^(\\d+) open(?: \\u00b7.*)?$", "function(m,n){return 'wazi '+n}"),
]
